// The light client's weak-subjectivity pin: macroblock K (index and MacroBlock::hash) with the committee-derivation
// anchors of K and K-1, so a walk starts at K instead of at genesis. It is the wallets' release pin, the block between
// the markers of applications/qnet-mobile/src/config/genesisConsensus.js (made by that app's scripts/ws-pin.js, each pin
// proven from the one before it), or one this site's scripts/light-pin.mjs --write-pin proved from it the same way; the
// site's tests keep the two on one lineage. The site proves no state at or below K: the pin carries K's committee data,
// not its state root. The block also carries NETWORK_ID (block 0's hash, as the wallets' block has it) and the capsule
// cadence a GALC v2 capsule (galc.ts) is checked against.
// <ws-pin>
// Generated by applications/qnet-explorer/frontend/scripts/light-pin.mjs on 2026-10-12 from 5 genesis nodes (certified head 39349; every macroblock QC-verified from the previous pin 38944).
export const WS_CHECKPOINT = {
  index: 39344,
  hash: '77bd7d3523f3a74d3c821f3d51269b66e27c7dc430ba42ad7f79bc0c5c00b988',
  provenFrom: { index: 38944, hash: 'dc72dc9384a46ad1c130ac49049aadd59355a74517a4aec55018f37b7c5d50ae' },
  anchors: {
    39344: {
      eligible_raw: '',
      beacon: '512f748941795e9560c3ca647a7773fb0979b54b9efe3826f135c16ea85482a8',
      registry_root: 'f5c896e1d5bb58b6b7378a53836dbfbe241cfc74aa2caf60297ae66e6f7dad04',
    },
    39343: {
      eligible_raw: '',
      beacon: 'b28b75826ba4d7094fa1f21fd3f899345d8ffda05d36e48715349219b317a498',
      registry_root: 'f5c896e1d5bb58b6b7378a53836dbfbe241cfc74aa2caf60297ae66e6f7dad04',
    },
  },
};
// Block 0's hash, served alike by every answering genesis node: the network_id a GALC v2 capsule must name.
export const NETWORK_ID = 'e5dbb7429eca37d346e9c41113403520fca83f354d6ce160cf57e06d9a92241f';
// Macroblocks between two genesis-signed capsules: the node's GALC_V2_MINT_INTERVAL.
export const GALC_V2_MINT_INTERVAL = 10;
// </ws-pin>

export interface PinAnchor { eligible_raw: string; beacon: string; registry_root: string }

/** The pin's anchor of macroblock `j` (K or K-1), or null. */
export function pinAnchor(j: number): PinAnchor | null {
  const anchors = WS_CHECKPOINT.anchors as Record<string, PinAnchor | undefined>;
  return anchors[String(j)] ?? null;
}
